input.sparql:
SELECT ?zone ?zoneName ?point ?pointName ?ts WHERE {
  ?ahu brick:isTypeOf* brick:AirHandlingUnit ;
       rdfs:label "AHU02" .
  ?zone brick:isServedBy ?ahu .
  OPTIONAL { ?zone rdfs:label ?zoneName }
  ?point brick:hasPropertyOf ?zone ;
         brick:isTypeOf* brick:AirTemperature .
  OPTIONAL { ?point rdfs:label ?pointName }
  ?point ref:hasTimeseriesId ?ts .
}

SELECT ?zone ?sensor ?ts WHERE {
  VALUES ?zone {
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z01>
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02>
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z03>
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z04>
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z05>
  }
  ?sensor brick:isTypeOf* brick:AirTemperature ;
          brick:isPointOf ?zone .
  ?sensor ref:hasTimeseriesId ?ts .
}

SELECT ?zone ?sensor ?ts WHERE {
  VALUES ?zone {
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z01>
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02>
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z03>
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z04>
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z05>
  }
  ?sensor brick:isTypeOf* brick:AirTemperature .
  ?zone brick:hasPoint ?sensor .
  ?sensor ref:hasTimeseriesId ?ts .
}

SELECT ?vav ?sensor ?extref WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#AHU02> brick:feeds ?vav .
  ?sensor rdf:type brick:Zone_Air_Temperature_Sensor ;
          brick:isPointOf ?vav .
  ?sensor ref:hasExternalReference ?extref .
}

SELECT ?sensor ?extref WHERE {
  ?sensor rdf:type brick:Zone_Air_Temperature_Sensor ;
          brick:isPointOf <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z03> ;
          ref:hasExternalReference ?extref .
}
